## `Makefile` — Auto-generate project folders

```makefile
# One-Day Alignment Kit Makefile
# Usage: make new PROJECT=mobile-search

.PHONY: new check help clean

# Default project name if not specified
PROJECT ?= untitled-project

help:
	@echo "One-Day Alignment Kit"
	@echo "===================="
	@echo "make new PROJECT=<name>  - Create new project folder with templates"
	@echo "make check              - Verify all template files exist"
	@echo "make clean              - Remove generated test folders"
	@echo ""
	@echo "Example: make new PROJECT=mobile-search"

new: check
	@echo "Creating project: $(PROJECT)"
	@mkdir -p "projects/$(PROJECT)"
	@# Copy templates with project name injected
	@sed 's/\[FILL: project name\]/$(PROJECT)/g' templates/decision-packet-1page.md > "projects/$(PROJECT)/decision-packet.md"
	@sed 's/\[FILL: project name\]/$(PROJECT)/g' templates/full-doc-template.md > "projects/$(PROJECT)/project-brief.md"
	@cp templates/jira-epic-template.txt "projects/$(PROJECT)/jira-epic.txt"
	@sed 's/\[Project\]/$(PROJECT)/g' templates/stakeholder-email-template.txt > "projects/$(PROJECT)/stakeholder-email.txt"
	@cp templates/escalation-template.md "projects/$(PROJECT)/escalation-template.md"
	@cp scripts/meeting-script.md "projects/$(PROJECT)/meeting-script.md"
	@cp scripts/objection-handlers.md "projects/$(PROJECT)/objection-handlers.md"
	@# Create status file
	@echo "PROJECT: $(PROJECT)" > "projects/$(PROJECT)/STATUS.md"
	@echo "CREATED: $$(date)" >> "projects/$(PROJECT)/STATUS.md"
	@echo "STATUS: Draft (v1.0)" >> "projects/$(PROJECT)/STATUS.md"
	@echo "" >> "projects/$(PROJECT)/STATUS.md"
	@echo "## Checklist" >> "projects/$(PROJECT)/STATUS.md"
	@echo "- [ ] Fill decision packet" >> "projects/$(PROJECT)/STATUS.md"
	@echo "- [ ] Send stakeholder email" >> "projects/$(PROJECT)/STATUS.md"
	@echo "- [ ] Schedule meeting" >> "projects/$(PROJECT)/STATUS.md"
	@echo "- [ ] Complete spikes" >> "projects/$(PROJECT)/STATUS.md"
	@echo "- [ ] Get decision" >> "projects/$(PROJECT)/STATUS.md"
	@echo "- [ ] Update to v1.2 FINAL" >> "projects/$(PROJECT)/STATUS.md"
	@echo "- [ ] Launch" >> "projects/$(PROJECT)/STATUS.md"
	@echo ""
	@echo "✅ Created: projects/$(PROJECT)/"
	@echo ""
	@echo "Next steps:"
	@echo "1. cd projects/$(PROJECT)"
	@echo "2. Fill decision-packet.md (Option A/B, deadlines, DRI)"
	@echo "3. Send stakeholder-email.txt"
	@echo "4. Start building Option A"

check:
	@echo "Checking template files..."
	@test -f templates/decision-packet-1page.md || (echo "❌ Missing decision-packet-1page.md" && exit 1)
	@test -f templates/full-doc-template.md || (echo "❌ Missing full-doc-template.md" && exit 1)
	@test -f templates/jira-epic-template.txt || (echo "❌ Missing jira-epic-template.txt" && exit 1)
	@test -f templates/stakeholder-email-template.txt || (echo "❌ Missing stakeholder-email-template.txt" && exit 1)
	@test -f templates/escalation-template.md || (echo "❌ Missing escalation-template.md" && exit 1)
	@test -f scripts/meeting-script.md || (echo "❌ Missing meeting-script.md" && exit 1)
	@test -f scripts/objection-handlers.md || (echo "❌ Missing objection-handlers.md" && exit 1)
	@echo "✅ All templates found"

clean:
	@echo "Cleaning test projects..."
	@rm -rf projects/test-* projects/untitled-*
	@echo "✅ Cleaned"
